def csv_files(folder):
    if not folder.exists() or not folder.is_dir():
        return []
    return sorted(folder.glob("*.csv"))


def reference_files():
    if not REFERENCE_FOLDER.exists() or not REFERENCE_FOLDER.is_dir():
        return []

    supported = {".txt", ".md", ".pdf", ".docx"}

    # Search recursively so a booklet inside a subfolder is still found.
    return sorted(
        p
        for p in REFERENCE_FOLDER.rglob("*")
        if p.is_file() and p.suffix.lower() in supported
    )


REFERENCE_CHUNK_SIZE = 2400
REFERENCE_CHUNK_OVERLAP = 300
REFERENCE_MAX_CONTEXT_CHARS = 14000
REFERENCE_TOP_K = 6

_STOP_WORDS = {
    "a", "an", "and", "are", "as", "at", "be", "by", "for", "from",
    "how", "i", "in", "is", "it", "of", "on", "or", "that", "the",
    "this", "to", "what", "when", "where", "which", "who", "why", "with",
    "you", "your", "can", "does", "do", "tell", "me", "about",
    "el", "la", "los", "las", "un", "una", "unos", "unas", "de", "del",
    "y", "o", "en", "por", "para", "que", "qué", "como", "cómo", "cual",
    "cuál", "es", "son", "se", "su", "sus", "me", "mi", "mis"
}


def _reference_tokens(text):
    """Local tokenizer with light normalization for PDF retrieval."""
    normalized = unicodedata.normalize("NFKD", text or "")
    normalized = "".join(
        ch for ch in normalized
        if not unicodedata.combining(ch)
    ).lower()

    # Treat British and American spelling as equivalent.
    normalized = normalized.replace("colours", "colors")
    normalized = normalized.replace("colour", "color")

    words = re.findall(r"[a-z0-9Δ]+", normalized)
    tokens = []

    for word in words:
        if len(word) <= 1 or word in _STOP_WORDS:
            continue

        tokens.append(word)

        if len(word) > 4 and word.endswith("s"):
            tokens.append(word[:-1])

    return tokens



def _split_reference_text(text, chunk_size=REFERENCE_CHUNK_SIZE,
                          overlap=REFERENCE_CHUNK_OVERLAP):
    """Split long extracted text without cutting normal words in half."""
    text = re.sub(r"[ \t]+", " ", text or "")
    text = re.sub(r"\n{3,}", "\n\n", text).strip()

    if not text:
        return []

    chunks = []
    start = 0
    length = len(text)

    while start < length:
        end = min(length, start + chunk_size)

        if end < length:
            # Prefer a paragraph boundary, then a sentence/space boundary.
            search_from = max(start + int(chunk_size * 0.65), start)
            candidates = [
                text.rfind("\n\n", search_from, end),
                text.rfind(". ", search_from, end),
                text.rfind(" ", search_from, end),
            ]
            boundary = max(candidates)
            if boundary > start:
                end = boundary + (2 if text[boundary:boundary + 2] == ". " else 0)

        chunk = text[start:end].strip()
        if chunk:
            chunks.append(chunk)

        if end >= length:
            break

        next_start = max(start + 1, end - overlap)

        # Move to the next whitespace boundary so a word is not split.
        while next_start < length and not text[next_start].isspace():
            next_start += 1

        start = next_start

    return chunks


def build_reference_index():
    """Read every local reference and create searchable chunks.

    PDFs are indexed page-by-page so retrieval can preserve page information.
    """
    chunks = []
    diagnostics = []

    for path in reference_files():
        suffix = path.suffix.lower()
        file_chunk_count = 0
        extracted_chars = 0

        try:
            if suffix == ".pdf":
                # PyMuPDF is already required by this application.
                # Search the local books page by page, including text PDFs.
                with fitz.open(str(path)) as document:
                    for page_number, page in enumerate(document, start=1):
                        page_text = (page.get_text("text", sort=True) or "").strip()
                        extracted_chars += len(page_text)
                        for chunk_text in _split_reference_text(page_text):
                            token_counts = Counter(_reference_tokens(chunk_text))
                            chunks.append({
                                "source": path.name,
                                "page": page_number,
                                "text": chunk_text,
                                "token_counts": token_counts,
                                "token_set": set(token_counts),
                            })
                            file_chunk_count += 1

            elif suffix in {".txt", ".md"}:
                raw = path.read_text(encoding="utf-8", errors="ignore")
                extracted_chars = len(raw)

                for chunk_text in _split_reference_text(raw):
                    token_counts = Counter(_reference_tokens(chunk_text))
                    chunks.append(
                        {
                            "source": path.name,
                            "page": None,
                            "text": chunk_text,
                            "token_counts": token_counts,
                            "token_set": set(token_counts),
                        }
                    )
                    file_chunk_count += 1

            elif suffix == ".docx":
                try:
                    from docx import Document
                except ImportError:
                    diagnostics.append(
                        f"{path.name}: NOT READ - install python-docx"
                    )
                    continue

                document = Document(str(path))
                raw = "\n".join(
                    paragraph.text
                    for paragraph in document.paragraphs
                    if paragraph.text.strip()
                )
                extracted_chars = len(raw)

                for chunk_text in _split_reference_text(raw):
                    token_counts = Counter(_reference_tokens(chunk_text))
                    chunks.append(
                        {
                            "source": path.name,
                            "page": None,
                            "text": chunk_text,
                            "token_counts": token_counts,
                            "token_set": set(token_counts),
                        }
                    )
                    file_chunk_count += 1

            if suffix == ".pdf" and extracted_chars == 0:
                diagnostics.append(
                    f"{path.name}: 0 characters, 0 searchable chunks "
                    f"(PDF may be scanned/image-only)"
                )
            else:
                diagnostics.append(
                    f"{path.name}: {extracted_chars:,} characters, "
                    f"{file_chunk_count} searchable chunks"
                )

        except Exception as error:
            diagnostics.append(f"{path.name}: ERROR - {error}")

    return chunks, diagnostics


def retrieve_reference_context(question, top_k=REFERENCE_TOP_K,
                               max_chars=REFERENCE_MAX_CONTEXT_CHARS):
    """Return the most relevant local reference chunks for one question."""
    # SCI/SCE are exact optical measurement modes; prioritize their literal
    # occurrence and expanded names, not unrelated generic color paragraphs.
    acronym_query = set(re.findall(r"\b(?:SCI|SCE)\b", question, re.I))
    acronym_query = {item.upper() for item in acronym_query}
    query_tokens = _reference_tokens(question)
    for acronym in acronym_query:
        query_tokens.extend([acronym.lower()] * 4)

    if not query_tokens or not REFERENCE_CHUNKS:
        return "", []

    query_counts = Counter(query_tokens)
    total_chunks = len(REFERENCE_CHUNKS)

    # Document frequency for only the terms in this query.
    document_frequency = {}
    for term in query_counts:
        document_frequency[term] = sum(
            1 for chunk in REFERENCE_CHUNKS if term in chunk["token_set"]
        )

    scored = []

    for index, chunk in enumerate(REFERENCE_CHUNKS):
        score = 0.0

        for term, query_tf in query_counts.items():
            tf = chunk["token_counts"].get(term, 0)
            if not tf:
                continue

            df = document_frequency.get(term, 0)
            idf = math.log((total_chunks + 1) / (df + 1)) + 1.0
            score += (1.0 + math.log(tf)) * idf * query_tf

        # Prefer chunks containing adjacent meaningful query terms.
        meaningful = list(dict.fromkeys(query_tokens))
        lowered = chunk["text"].lower()
        for left, right in zip(meaningful, meaningful[1:]):
            if f"{left} {right}" in lowered:
                score += 2.5

        if acronym_query:
            present = {term for term in acronym_query
                       if re.search(r"\b" + term + r"\b", chunk["text"], re.I)}
            if present:
                score += 35.0 * len(present)
            elif score < 8.0:
                score = 0.0
        if score > 0:
            scored.append((score, index, chunk))

    if not scored:
        return "", []

    scored.sort(key=lambda item: (-item[0], item[1]))

    # Keep results close to the strongest match and avoid weak unrelated sources.
    best_score = scored[0][0]
    selected = []
    source_names = []
    used_chars = 0

    for score, _, chunk in scored:
        if len(selected) >= top_k:
            break

        if score < best_score * 0.30:
            break

        page_label = (
            f" | Page {chunk['page']}"
            if chunk["page"] is not None
            else ""
        )

        block = (
            f"\n--- LOCAL SOURCE: {chunk['source']}{page_label} ---\n"
            f"{chunk['text']}\n"
        )

        if used_chars + len(block) > max_chars:
            remaining = max_chars - used_chars
            if remaining <= 300:
                break
            block = block[:remaining]

        selected.append(block)
        used_chars += len(block)

        if chunk["source"] not in source_names:
            source_names.append(chunk["source"])

    # Limit the source line to the strongest one or two actual retrieved files.
    return "".join(selected), source_names[:2]



def preview_csv(path, max_rows=20):
    """Return a small CSV preview for Ollama instead of loading huge files."""
    try:
        rows = []
        with path.open(
            "r", encoding="utf-8-sig", errors="ignore", newline=""
        ) as f:
            reader = csv.reader(f)
            for index, row in enumerate(reader):
                rows.append(", ".join(row))
                if index >= max_rows:
                    break
        return "\n".join(rows)
    except Exception as error:
        return f"Could not read {path.name}: {error}"



def is_image_request(question):
    q = (question or "").lower()
    visual_words = (
        "show me", "display", "picture", "image", "photo", "figure", "diagram",
        "representation", "muéstrame", "muestrame", "mostrar", "imagen", "foto",
        "figura", "diagrama", "representación", "representacion"
    )
    return any(word in q for word in visual_words)


def _normalize_model_text(text):
    """Normalize model names so CM-26dG, CM 26DG and spoken 'twenty six DG' match."""
    value = (text or "").lower()
    replacements = {
        "twenty six": "26",
        "twenty-six": "26",
        "twenty  six": "26",
        "d g": "dg",
    }
    for old, new_value in replacements.items():
        value = value.replace(old, new_value)
    return re.sub(r"[^a-z0-9]+", "", value)

def _requested_model_from_question(question, pdfs):
    """Return the best matching model token using both the question and local PDF names."""
    normalized_question = _normalize_model_text(question)

    direct = re.search(r"(?:cm|cr|cl|cs)\s*[- ]?\s*\d+[a-z0-9-]*", (question or "").lower())
    if direct:
        return _normalize_model_text(direct.group(0))

    known_models = []
    for pdf in pdfs:
        normalized_name = _normalize_model_text(pdf.stem)
        known_models.extend(re.findall(r"(?:cm|cr|cl|cs)\d+[a-z0-9]*", normalized_name))

    # Longest model first avoids choosing CM26 when the file contains CM26dG.
    for model in sorted(set(known_models), key=len, reverse=True):
        short_model = re.sub(r"^(?:cm|cr|cl|cs)", "", model)
        if model in normalized_question or (len(short_model) >= 3 and short_model in normalized_question):
            return model
    return ""

def _image_rectangles(page):
    """Return visible image rectangles without extracting the raster resources themselves."""
    rects = []
    page_rect = page.rect
    min_area = max(1.0, page_rect.get_area() * 0.005)
    try:
        for item in page.get_images(full=True):
            xref = item[0]
            try:
                image_rects = page.get_image_rects(xref)
            except Exception:
                image_rects = []
            for rect in image_rects:
                rect = fitz.Rect(rect) & page_rect
                if rect.get_area() >= min_area:
                    rects.append(rect)
    except Exception:
        pass
    return rects

def _model_search_labels(requested_model):
    """Return human-readable variants for a normalized model token such as cm700d."""
    model = (requested_model or "").lower()
    match = re.match(r"^(cm|cr|cl|cs)([0-9][a-z0-9]*)$", model)
    if not match:
        return []
    prefix, suffix = match.groups()
    prefix = prefix.upper()
    suffix_upper = suffix.upper()
    return [
        f"{prefix}-{suffix_upper}",
        f"{prefix} {suffix_upper}",
        f"{prefix}{suffix_upper}",
        suffix_upper,
    ]


def _best_visual_clip(page, requested_model=""):
    """Choose a complete image cluster, preferring artwork nearest the requested model label."""
    rects = _image_rectangles(page)
    if not rects:
        return None

    # Merge overlapping / nearby image rectangles. PDF product photos are often
    # composed from several masks and image resources, so a union keeps the
    # display, housing and highlights together instead of extracting one layer.
    clusters = []
    gap = max(page.rect.width, page.rect.height) * 0.025
    for rect in rects:
        expanded = fitz.Rect(rect.x0-gap, rect.y0-gap, rect.x1+gap, rect.y1+gap)
        merged = False
        for index, current in enumerate(clusters):
            current_expanded = fitz.Rect(current.x0-gap, current.y0-gap, current.x1+gap, current.y1+gap)
            if expanded.intersects(current_expanded):
                clusters[index] = current | rect
                merged = True
                break
        if not merged:
            clusters.append(fitz.Rect(rect))

    changed = True
    while changed:
        changed = False
        result = []
        while clusters:
            current = clusters.pop(0)
            i = 0
            while i < len(clusters):
                a = fitz.Rect(current.x0-gap, current.y0-gap, current.x1+gap, current.y1+gap)
                b = fitz.Rect(clusters[i].x0-gap, clusters[i].y0-gap, clusters[i].x1+gap, clusters[i].y1+gap)
                if a.intersects(b):
                    current |= clusters.pop(i)
                    changed = True
                else:
                    i += 1
            result.append(current)
        clusters = result

    page_area = max(1.0, page.rect.get_area())
    candidates = []
    for rect in clusters:
        ratio = rect.get_area() / page_area
        if 0.025 <= ratio <= 0.82:
            aspect = rect.width / max(rect.height, 1.0)
            shape_bonus = 1.0 if 0.35 <= aspect <= 2.8 else 0.7
            candidates.append((rect.get_area() * shape_bonus, rect))

    if not candidates:
        return None

    # If the user named a model, prefer the visual nearest that model's printed
    # label/caption. This prevents a page containing CM-5 + CM-700d from
    # returning the larger but wrong instrument.
    target_rects = []
    if requested_model:
        for label in _model_search_labels(requested_model):
            try:
                target_rects.extend(page.search_for(label))
            except Exception:
                pass

    if target_rects:
        def distance_to_target(item):
            area_score, rect = item
            cx = (rect.x0 + rect.x1) / 2.0
            cy = (rect.y0 + rect.y1) / 2.0
            best_distance = min(
                ((cx - ((t.x0+t.x1)/2.0)) ** 2 + (cy - ((t.y0+t.y1)/2.0)) ** 2) ** 0.5
                for t in target_rects
            )
            # Distance dominates; larger complete artwork breaks close ties.
            return (best_distance, -area_score)

        _, rect = min(candidates, key=distance_to_target)
    else:
        _, rect = max(candidates, key=lambda item: item[0])

    pad_x = rect.width * 0.06
    pad_y = rect.height * 0.06
    return fitz.Rect(
        max(page.rect.x0, rect.x0-pad_x),
        max(page.rect.y0, rect.y0-pad_y),
        min(page.rect.x1, rect.x1+pad_x),
        min(page.rect.y1, rect.y1+pad_y),
    )

def _save_best_visual_from_page(document, page, pdf_path, page_number, requested_model=""):
    """Render the visual region while preserving all PDF layers and masks."""
    safe_stem = re.sub(r"[^A-Za-z0-9._-]+", "_", pdf_path.stem)[:80]
    output_path = IMAGE_CACHE_FOLDER / f"{safe_stem}_p{page_number}_visual.png"

    clip = _best_visual_clip(page, requested_model=requested_model)
    matrix = fitz.Matrix(2.5, 2.5)
    if clip is not None:
        pixmap = page.get_pixmap(matrix=matrix, clip=clip, alpha=False)
        visual_kind = "rendered visual region"
    else:
        # Fallback keeps the page intact rather than extracting one broken layer.
        pixmap = page.get_pixmap(matrix=matrix, alpha=False)
        visual_kind = "rendered page"

    pixmap.save(str(output_path))
    return output_path, visual_kind

def find_pdf_visual(question):
    """Find a strongly supported PDF visual; never fall back to an unrelated first page."""
    pdfs = [path for path in reference_files() if path.suffix.lower() == ".pdf"]
    if not pdfs:
        return {"error": "I could not find a PDF in the local reference folder."}

    q = (question or "").lower()
    terms = list(dict.fromkeys(_reference_tokens(question)))
    visual_only_terms = {
        "show", "display", "picture", "image", "photo", "figure", "diagram",
        "representation", "mostrar", "muestrame", "imagen", "foto", "figura",
        "diagrama", "representacion", "just", "only", "something", "algo",
    }
    evidence_terms = [term for term in terms if term not in visual_only_terms]
    requested_model = _requested_model_from_question(question, pdfs)
    generic_instrument_request = any(
        word in q
        for word in (
            "spectrophotometer", "spectrofotometro", "spectrofotómetro",
            "colorimeter", "colorimetro", "colorímetro",
            "instrument", "instrumento", "device", "equipo",
        )
    )
    wants_full_instrument = generic_instrument_request or any(
        phrase in q
        for phrase in (
            "picture of", "photo of", "image of", "show me", "can i see",
            "whole instrument", "full instrument", "foto de", "imagen de",
            "muéstrame", "muestrame", "completo", "completa",
        )
    )
    page_match = re.search(r"(?:page|pagina|página)\s*(\d+)", q)
    requested_page = int(page_match.group(1)) if page_match else None

    def file_has_model_name(pdf):
        return bool(re.search(r"(?:cm|cr|cl|cs)\d+[a-z0-9]*", _normalize_model_text(pdf.stem)))

    if requested_model:
        model_pdfs = [pdf for pdf in pdfs if requested_model in _normalize_model_text(pdf.name)]
        if not model_pdfs:
            short_model = re.sub(r"^(?:cm|cr|cl|cs)", "", requested_model)
            model_pdfs = [pdf for pdf in pdfs if short_model and short_model in _normalize_model_text(pdf.name)]
        if not model_pdfs:
            return {"error": f"I could not find a local PDF for {requested_model.upper()}."}
        candidates = model_pdfs
    else:
        explicit_pdfs = [pdf for pdf in pdfs if pdf.name.lower() in q or pdf.stem.lower() in q]
        if explicit_pdfs:
            candidates = explicit_pdfs
        elif generic_instrument_request:
            # A generic request such as "show me a spectrophotometer" should
            # choose an actual instrument manual, never a theory/article PDF.
            instrument_pdfs = [pdf for pdf in pdfs if file_has_model_name(pdf)]
            if not instrument_pdfs:
                instrument_pdfs = [
                    pdf for pdf in pdfs
                    if any(word in pdf.name.lower() for word in ("spectrophotometer", "instrument", "manual"))
                ]
            if not instrument_pdfs:
                return {"error": "I could not find a spectrophotometer image in the local PDF files."}
            candidates = instrument_pdfs
        else:
            candidates = pdfs

    best = None
    for pdf in candidates:
        filename_lower = pdf.name.lower()
        normalized_file = _normalize_model_text(filename_lower)
        filename_score = sum(6 for term in evidence_terms if term in filename_lower)
        if requested_model and requested_model in normalized_file:
            filename_score += 80
        elif generic_instrument_request and file_has_model_name(pdf):
            filename_score += 24

        try:
            with fitz.open(str(pdf)) as document:
                page_indices = [requested_page-1] if requested_page is not None else range(len(document))
                for page_index in page_indices:
                    if page_index < 0 or page_index >= len(document):
                        continue

                    page = document[page_index]
                    page_text = page.get_text("text") or ""
                    page_lower = page_text.lower()
                    normalized_page = _normalize_model_text(page_lower)
                    term_hits = sum(min(page_lower.count(term), 5) for term in evidence_terms)
                    score = float(filename_score) + term_hits * 3.0

                    if requested_model and requested_model in normalized_page:
                        score += 35

                    rects = _image_rectangles(page)
                    if rects:
                        max_ratio = max(rect.get_area() / max(page.rect.get_area(), 1.0) for rect in rects)
                        if 0.04 <= max_ratio <= 0.70:
                            score += 7
                        elif max_ratio > 0.90:
                            score -= 2
                    else:
                        score -= 8

                    if wants_full_instrument and requested_page is None:
                        score += max(0.0, 18.0 - page_index * 2.0)
                        if page_index == 0:
                            score += 8

                        positive = {
                            "overview": 12, "names of parts": 12, "parts": 7,
                            "instrument": 7, "spectrophotometer": 9,
                            "appearance": 5, "product": 4, "introduction": 4,
                        }
                        negative = {
                            "targets": 16, "target": 8, "menu": 10,
                            "screen": 10, "display settings": 14,
                            "settings": 5, "measurement screen": 10,
                        }
                        for phrase, bonus in positive.items():
                            if phrase in page_lower:
                                score += bonus
                        for phrase, penalty in negative.items():
                            if phrase in page_lower:
                                score -= penalty

                    # Evidence is tracked separately from layout bonuses so an
                    # unrelated page cannot win merely because it is page 1.
                    evidence = filename_score + term_hits * 3.0
                    if requested_model and requested_model in normalized_page:
                        evidence += 35
                    candidate = (score, evidence, pdf, page_index, page_text)
                    if best is None or candidate[0] > best[0]:
                        best = candidate
        except Exception:
            continue

    if best is None:
        return {"error": "I could not open the available PDF files."}

    score, evidence, pdf_path, page_index, page_text = best

    # Critical guard: never show an arbitrary fallback image. Exact models need
    # model evidence; generic/topic requests need at least one real topical hit.
    if requested_model:
        if evidence < 45:
            return {"error": f"I found the {requested_model.upper()} reference, but not a reliable image for that model in the local PDF files."}
    elif generic_instrument_request:
        if evidence < 18:
            return {"error": "I could not find a reliable spectrophotometer image in the local PDF files."}
    else:
        if not evidence_terms or evidence <= 0:
            return {"error": "I could not find a matching visual in the local reference documents."}

    try:
        with fitz.open(str(pdf_path)) as document:
            page = document[page_index]
            image_path, visual_kind = _save_best_visual_from_page(
                document,
                page,
                pdf_path,
                page_index + 1,
                requested_model=requested_model,
            )
    except Exception as error:
        return {"error": f"I found the PDF page but could not render its image: {error}"}

    return {
        "path": image_path,
        "pdf_name": pdf_path.name,
        "page_number": page_index + 1,
        "page_text": page_text[:5000],
        "visual_kind": visual_kind,
    }

def build_measurement_context(question):
    """Add CSV context only when the question appears to ask about measurements.

    If the user mentions a specific filename, that file is preferred.
    Otherwise one small preview from Targets and one from Samples is supplied.
    """
    q = question.lower()
    keywords = (
        "spectral",
        "measurement",
        "measurements",
        "target",
        "targets",
        "sample",
        "samples",
        "csv",
        "data",
        "delta e",
        "reflectance",
    )

    if not any(word in q for word in keywords):
        return ""

    targets = csv_files(TARGETS_FOLDER)
    samples = csv_files(SAMPLES_FOLDER)
    all_files = targets + samples

    chosen = []

    # Prefer any filename explicitly mentioned in the question.
    for path in all_files:
        if path.name.lower() in q or path.stem.lower() in q:
            chosen.append(path)

    # Otherwise give a small representative preview.
    if not chosen:
        if targets:
            chosen.append(targets[0])
        if samples:
            chosen.append(samples[0])

    if not chosen:
        return (
            "No CSV measurement files were found. Check TARGETS_FOLDER and "
            "SAMPLES_FOLDER in color_agent_main.py."
        )

    blocks = []
    for path in chosen[:3]:
        kind = "Target" if path in targets else "Sample"
        blocks.append(
            f"\n--- {kind} CSV: {path.name} ---\n{preview_csv(path)}\n"
        )

    return "".join(blocks)


