def _render_crop(canvas, crop_box, width, height, cache_key):
    """Keep the approved default proportions; fullscreen adds space instead of stretching art."""
    width = max(1, int(width))
    height = max(1, int(height))
    crop = _design_source.crop(crop_box)

    # These are the approximate on-screen dimensions of the approved design at
    # the normal 1280x820 window.  The artwork may shrink with a smaller window,
    # but it is never enlarged past these dimensions when the user maximizes.
    approved_max = {
        "header": (1280, 158),
        "sidebar": (205, 654),
        "capabilities": (355, 568),
        "footer": (1070, 86),
    }
    max_w, max_h = approved_max.get(cache_key, (width, height))
    draw_w = width if cache_key == "header" else min(width, max_w)
    draw_h = min(height, max_h)

    resized = crop.resize((draw_w, draw_h), Image.LANCZOS)
    x_off = max(0, (width - draw_w) // 2)
    if cache_key in {"sidebar", "capabilities"}:
        y_off = 0
    else:
        y_off = max(0, (height - draw_h) // 2)

    fill = {"sidebar": "#F4F0FF", "capabilities": "#F4F0FF", "header": "#FAF8FF"}.get(cache_key, crop.getpixel((0, 0)))
    background = Image.new("RGB", (width, height), fill)
    background.paste(resized, (x_off, y_off))
    photo = ImageTk.PhotoImage(background)
    _photo_refs[cache_key] = photo
    _render_transforms[cache_key] = (x_off, y_off, draw_w, draw_h, 1.0)

    canvas.delete("design_bg")
    canvas.create_image(0, 0, image=photo, anchor="nw", tags="design_bg")
    canvas.tag_lower("design_bg")


