def _rounded_rect(canvas, x1, y1, x2, y2, radius, **kwargs):
    points = [
        x1 + radius, y1,
        x2 - radius, y1,
        x2, y1,
        x2, y1 + radius,
        x2, y2 - radius,
        x2, y2,
        x2 - radius, y2,
        x1 + radius, y2,
        x1, y2,
        x1, y2 - radius,
        x1, y1 + radius,
        x1, y1,
    ]
    return canvas.create_polygon(
        points, smooth=True, splinesteps=24, **kwargs
    )


class RoundedBubble(tk.Frame):
    """Rounded bubble with normal word wrapping and streaming support."""

    def __init__(self, parent, text, fill, fg, max_width=500, tail="left"):
        super().__init__(parent, bg=parent.cget("bg"), bd=0)
        self.fill = fill
        self.max_width = max(120, int(max_width))
        self.tail = tail

        # Streaming UI state.  Throttle geometry refreshes so the whole chat
        # does not flicker while Ollama is delivering many tiny chunks.
        self._streaming = False
        self._refresh_after_id = None

        self.canvas = tk.Canvas(
            self,
            bg=parent.cget("bg"),
            highlightthickness=0,
            bd=0,
        )
        self.canvas.pack(fill="both", expand=True)

        self.label = tk.Label(
            self.canvas,
            text=text,
            justify="left",
            anchor="nw",
            wraplength=self.max_width,
            font=("Segoe UI", 10),
            bg=fill,
            fg=fg,
            bd=0,
        )

        self.label_window = self.canvas.create_window(
            24 if tail == "left" else 14,
            10,
            window=self.label,
            anchor="nw",
        )

        self._refresh_shape()

    def set_max_width(self, width):
        """Update the usable text width when the chat panel changes size."""
        width = max(120, int(width))
        if width != self.max_width:
            self.max_width = width
            self._schedule_refresh(0 if not self._streaming else 50)

    def set_streaming(self, value):
        """Keep the bubble stable while streamed text is arriving."""
        value = bool(value)
        if value == self._streaming:
            return

        self._streaming = value

        # When streaming ends, discard any delayed refresh.  The caller does
        # one final geometry pass after the complete answer/Source is inserted.
        if not value and self._refresh_after_id is not None:
            try:
                self.after_cancel(self._refresh_after_id)
            except tk.TclError:
                pass
            self._refresh_after_id = None

    def _schedule_refresh(self, delay=50):
        """At most one pending geometry refresh at a time."""
        if self._refresh_after_id is not None:
            return

        def run_refresh():
            self._refresh_after_id = None
            try:
                self._refresh_shape()
            except tk.TclError:
                pass

        if delay <= 0:
            self._refresh_after_id = self.after_idle(run_refresh)
        else:
            self._refresh_after_id = self.after(delay, run_refresh)

    def _refresh_shape(self):
        # Normal word wrapping: if the next word does not fit, it moves
        # to the next line instead of being clipped.
        self.label.configure(wraplength=self.max_width)
        self.label.update_idletasks()

        # While streaming, keep the width fixed so each new word does not
        # make the whole row shift left/right.  Only the height grows.
        if self._streaming:
            label_w = self.max_width
        else:
            label_w = min(self.max_width, max(40, self.label.winfo_reqwidth()))
        label_h = max(20, self.label.winfo_reqheight())

        left_pad = 24 if self.tail == "left" else 14
        right_pad = 14 if self.tail == "left" else 24

        width = label_w + left_pad + right_pad
        height = label_h + 20

        # Configure the actual Frame.  Do not call self.configure() here,
        # because configure() below is intentionally redirected to the label
        # so streamed text can keep using bubble.config(text=...).
        tk.Frame.configure(self, width=width, height=height)
        self.canvas.configure(width=width, height=height)

        self.canvas.delete("bubble_shape")

        _rounded_rect(
            self.canvas,
            10 if self.tail == "left" else 0,
            0,
            width if self.tail == "left" else width - 10,
            height,
            18,
            fill=self.fill,
            outline="",
            tags="bubble_shape",
        )

        if self.tail == "left":
            self.canvas.create_polygon(
                2, 22, 16, 14, 16, 31,
                fill=self.fill,
                outline="",
                tags="bubble_shape",
            )
        else:
            self.canvas.create_polygon(
                width - 2, 22,
                width - 16, 14,
                width - 16, 31,
                fill=self.fill,
                outline="",
                tags="bubble_shape",
            )

        self.canvas.tag_lower("bubble_shape")
        self.canvas.coords(
            self.label_window,
            24 if self.tail == "left" else 14,
            10,
        )

        self.after_idle(_update_chat_scroll)

    def config(self, cnf=None, **kwargs):
        """Keep .config(text=...) compatible with streamed Ollama output."""
        if cnf:
            kwargs.update(cnf)

        if "text" in kwargs:
            self.label.config(text=kwargs.pop("text"))
            # During streaming, refresh on a short timer instead of once per
            # token.  Outside streaming, refresh immediately on the next idle.
            self._schedule_refresh(50 if self._streaming else 0)

        if kwargs:
            self.label.config(**kwargs)

    configure = config


def add_message(role, text):
    row = tk.Frame(chat_inner, bg="#FCFCFE")
    row.pack(fill="x", padx=8, pady=7)

    # Temporary width only.  As soon as Tkinter lays out the row,
    # the <Configure> event below replaces it with the real available width.
    initial_width = 420

    if role == "assistant":
        avatar = tk.Label(
            row,
            image=_avatar_photo(),
            bg="#FCFCFE",
            bd=0,
        )
        avatar.image = _avatar_photo()
        avatar.pack(side="left", anchor="n", padx=(0, 8))

        bubble = RoundedBubble(
            row,
            text,
            fill="#EEE7FF",
            fg="#17153E",
            max_width=initial_width,
            tail="left",
        )
        bubble.pack(side="left", anchor="nw", padx=(0, 8))

        def resize_bubble(event):
            # IMPORTANT: max_width is the LABEL/text width, not the total
            # rounded bubble width.  Reserve space for the avatar, pack gaps,
            # AND the bubble's own left/right padding so the right edge never
            # extends past the visible chat area.
            usable = max(180, event.width - 102)
            bubble.set_max_width(usable)

    else:
        bubble = RoundedBubble(
            row,
            text,
            fill="#6F35D3",
            fg="#FFFFFF",
            max_width=initial_width,
            tail="right",
        )
        bubble.pack(side="right", anchor="ne", padx=(8, 0))

        def resize_bubble(event):
            # Reserve the pack gap plus the bubble's 38 px internal padding.
            # Otherwise the canvas becomes wider than the row and clips text.
            usable = max(180, event.width - 46)
            bubble.set_max_width(usable)

    # This is the key part: the bubble follows the REAL chat width,
    # including future window resizing.
    row.bind("<Configure>", resize_bubble, add="+")
    row.after_idle(
        lambda: bubble.set_max_width(
            max(
                180,
                row.winfo_width() - (102 if role == "assistant" else 46)
            )
        )
    )

    root.after_idle(scroll_to_bottom)
    return bubble



def add_image_message(image_path, caption=""):
    """Display a PDF image inside the same scrolling chat conversation."""
    row = tk.Frame(chat_inner, bg="#FCFCFE")
    row.pack(fill="x", padx=8, pady=7)

    avatar = tk.Label(
        row,
        image=_avatar_photo(),
        bg="#FCFCFE",
        bd=0,
    )
    avatar.image = _avatar_photo()
    avatar.pack(side="left", anchor="n", padx=(0, 8))

    bubble = tk.Frame(row, bg="#EEE7FF", bd=0, padx=10, pady=10)
    bubble.pack(side="left", anchor="w", padx=(0, 45))

    try:
        image = Image.open(image_path).convert("RGB")
        image.thumbnail((540, 440), Image.LANCZOS)
        photo = ImageTk.PhotoImage(image)

        image_label = tk.Label(bubble, image=photo, bg="#EEE7FF", bd=0)
        image_label.image = photo
        image_label.pack(anchor="w")

        key = f"chat_image_{len(_photo_refs)}"
        _photo_refs[key] = photo

        if caption:
            tk.Label(
                bubble,
                text=caption,
                justify="left",
                anchor="w",
                wraplength=520,
                font=("Segoe UI", 9),
                bg="#EEE7FF",
                fg="#40386B",
                pady=6,
            ).pack(anchor="w")
    except Exception as error:
        tk.Label(
            bubble,
            text=f"Could not display image: {error}",
            justify="left",
            anchor="w",
            wraplength=500,
            font=("Segoe UI", 10),
            bg="#EEE7FF",
            fg="#B42318",
        ).pack(anchor="w")

    root.after_idle(scroll_to_bottom)
    return bubble


