def remove_placeholder(event=None):
    if textbox_ask.get("1.0", tk.END).strip() == PLACEHOLDER:
        textbox_ask.delete("1.0", tk.END)
        textbox_ask.configure(fg="#21194F")


def add_placeholder(event=None):
    if not textbox_ask.get("1.0", tk.END).strip():
        textbox_ask.insert("1.0", PLACEHOLDER)
        textbox_ask.configure(fg="#655F7B")


textbox_ask.bind("<FocusIn>", remove_placeholder)
textbox_ask.bind("<FocusOut>", add_placeholder)


def _resize_footer(event):
    """Fit the input to the actual footer instead of a centered fixed-size bitmap.

    The original centered footer left a white rectangle and placed the editable
    Text control over the wrong part of the Send artwork when maximized.
    """
    width, height = max(1, event.width), max(1, event.height)
    artwork = _design_source.crop(CROP_FOOTER)
    # Preserve the original layout, but use the available width so that the
    # input and Send button stay together without a blank strip.
    photo = ImageTk.PhotoImage(artwork.resize((width, height), Image.LANCZOS))
    _photo_refs["footer"] = photo
    footer_canvas.delete("design_bg")
    footer_canvas.create_image(0, 0, image=photo, anchor="nw", tags="design_bg")
    footer_canvas.tag_lower("design_bg")
    _render_transforms["footer"] = (0, 0, width, height, 1.0)

    # Leave the scientist illustration and the Send button unobstructed.
    # The artwork has a 12% left avatar, a 64% input and a 21% Send button.
    # The editable text stays entirely inside the painted input, at all sizes.
    x = int(width * 0.165)
    h = max(40, min(50, int(height * 0.50)))
    y = max(0, (height - h) // 2 - 8)
    w = max(80, int(width * 0.54))
    footer_canvas.coords(textbox_window, x, y)
    footer_canvas.itemconfigure(textbox_window, width=w, height=h)
    footer_canvas.tag_raise(textbox_window)

footer_canvas.bind("<Configure>", _resize_footer)

