def new_session():
    global processing
    if processing or not new_session_enabled:
        return

    bot.new_session()
    clear_chat()
    add_welcome_message()


def _sidebar_click(event):
    # Regions are derived from the approved sidebar artwork, which is no longer
    # vertically stretched when the window is maximized.
    _, y_off, _, draw_h, _ = _render_transforms.get(
        "sidebar", (0, 0, sidebar_canvas.winfo_width(), sidebar_canvas.winfo_height(), 1.0)
    )
    if not (y_off <= event.y <= y_off + draw_h):
        return
    y_ratio = (event.y - y_off) / max(1, draw_h)

    # Chat: approximately 4%–14% of the sidebar height.
    if 0.04 <= y_ratio <= 0.15:
        textbox_ask.focus_set()
        return

    # New Session: approximately 15%–24%.
    if 0.15 < y_ratio <= 0.25:
        new_session()
        return

sidebar_canvas.bind("<Button-1>", _sidebar_click)

# ============================================================
# OLLAMA STREAMING — original behavior preserved
# ============================================================


def set_processing(value):
    global processing, send_enabled, new_session_enabled
    processing = value
    send_enabled = not value
    new_session_enabled = not value


def append_chunk(label, state, chunk):
    state["text"] += chunk

    # Keep real-time streaming, but do not force a complete layout/scroll pass
    # for every tiny Ollama token.  RoundedBubble throttles geometry updates to
    # roughly every 50 ms and keeps its width stable while the answer grows.
    label.set_streaming(True)
    label.config(text=state["text"])


def _strip_model_source_lines(answer):
    """The application, not the model, owns the verified Source line."""
    lines = []
    for line in (answer or "").splitlines():
        if re.match(r"^\s*Sources?\s*:", line, flags=re.IGNORECASE):
            continue
        lines.append(line)
    return "\n".join(lines).rstrip()


def response_finished(response_label, state, source_names, casual):
    final_text = _strip_model_source_lines(state["text"])

    if not casual:
        not_found_phrase = (
            "i could not find that information in the local reference documents"
        )

        if (
            not source_names
            or not_found_phrase in final_text.lower()
        ):
            source_line = "Source: Not found in local documents"
        elif len(source_names) == 1:
            source_line = f"Source: {source_names[0]}"
        else:
            source_line = "Sources: " + ", ".join(source_names)

        final_text = final_text.rstrip() + "\n\n" + source_line

    state["text"] = final_text
    response_label.set_streaming(False)
    response_label.config(text=final_text)

    # Re-measure AFTER the verified Source line has been appended.  Tkinter can
    # need more than one idle cycle for the bubble -> row -> chat_inner geometry
    # to propagate, so do an immediate refresh and two short follow-up refreshes.
    # This makes the Source line visible immediately, without requiring the user
    # to send another message first.
    def finalize_response_view():
        try:
            response_label._refresh_shape()
            response_label.update_idletasks()
            response_label.master.update_idletasks()
            chat_inner.update_idletasks()
            _update_chat_scroll()
            chat_region.update_idletasks()
            chat_region.yview_moveto(1.0)
        except tk.TclError:
            # The window may have been closed while a streamed response finished.
            pass

    finalize_response_view()
    root.after_idle(finalize_response_view)
    root.after(40, finalize_response_view)
    root.after(120, finalize_response_view)
    set_processing(False)


def response_error(label, error_message):
    label.set_streaming(False)
    label.config(text="I could not complete the response.\n\n" + error_message)
    label.after_idle(label._refresh_shape)
    set_processing(False)


def ask_ollama(question, response_label, state):
    try:
        # Image/figure requests stay local: find one relevant PDF page and show it.
        # Do not send the entire PDF to Ollama, which avoids the context-size error.
        if is_image_request(question):
            visual = find_pdf_visual(question)
            if visual.get("error"):
                root.after(0, show_visual_error, response_label, visual["error"])
            else:
                root.after(0, show_pdf_visual, response_label, visual)
            return

        casual = bot.is_casual_message(question)
        source_names = []

        if casual:
            extra_context = ""
        else:
            reference_context, source_names = retrieve_reference_context(question)
            measurement_context = build_measurement_context(question)

            # Measurement CSVs remain local context too.
            if measurement_context:
                csv_sources = re.findall(
                    r"--- (?:Target|Sample) CSV: (.+?) ---",
                    measurement_context,
                )
                for source in csv_sources:
                    if source not in source_names:
                        source_names.append(source)

            extra_context = "\n".join(
                part
                for part in (reference_context, measurement_context)
                if part.strip()
            )

        for chunk in bot.user_message(
            question,
            extra_context=extra_context,
        ):
            root.after(0, append_chunk, response_label, state, chunk)

        root.after(
            0,
            response_finished,
            response_label,
            state,
            source_names,
            casual,
        )

    except Exception as error:
        root.after(0, response_error, response_label, str(error))



def _is_spanish_text(text):
    """Return True when the current user message is likely Spanish."""
    value = f" {(text or '').lower()} "
    spanish_markers = (
        " que ", " qué ", " como ", " cómo ", " quiero ", " puedes ", " puede ",
        " mostrar ", " muéstrame ", " muestrame ", " imagen ", " foto ",
        " instrumento ", " datos ", " color ", " medición ", " medicion ",
        " necesito ", " dime ", " por favor ",
    )
    accented = any(ch in value for ch in "áéíóúñ¿¡")
    marker_hits = sum(marker in value for marker in spanish_markers)
    return accented or marker_hits >= 2

def send_text():
    if processing or not send_enabled:
        return

    question = textbox_ask.get("1.0", tk.END).strip()

    if not question or question == PLACEHOLDER:
        return

    add_message("user", question)
    textbox_ask.delete("1.0", tk.END)

    status_text = "Pensando..." if _is_spanish_text(question) else "Thinking..."
    response_label = add_message("assistant", status_text)
    state = {"text": ""}
    set_processing(True)

    # Paint both bubbles before Ollama starts streaming. This prevents the
    # transient white/empty half-bubble that could appear immediately after Send.
    root.update_idletasks()
    _update_chat_scroll()
    chat_region.yview_moveto(1.0)

    worker = threading.Thread(
        target=ask_ollama,
        args=(question, response_label, state),
        daemon=True,
    )
    worker.start()

def _footer_click(event):
    # Map clicks to the undistorted footer artwork instead of the whole
    # maximized canvas, so Send remains aligned in fullscreen.
    x_off, y_off, draw_w, draw_h, _ = _render_transforms.get(
        "footer", (0, 0, footer_canvas.winfo_width(), footer_canvas.winfo_height(), 1.0)
    )
    inside_y = y_off <= event.y <= y_off + draw_h
    if inside_y and event.x >= x_off + draw_w * 0.82 and event.x <= x_off + draw_w:
        send_text()


footer_canvas.bind("<Button-1>", _footer_click)


def enter_pressed(event):
    # Shift+Enter adds a new line; Enter sends.
    if event.state & 0x0001:
        return None

    send_text()
    return "break"


textbox_ask.bind("<Return>", enter_pressed)

